1	// 参数化 single-beat AXI-like crossbar。
2	// 当前 NPC cache miss 侧还没有 AXI4 ID/burst，本模块先把 valid/ready 通道、
3	// 地址译码和 response route 独立出来，后续扩设备时不再改 core/cache。
4	
5	module AxiLiteXbar #(
6	  parameter ADDR_W = 32,
7	  parameter DATA_W = 32,
8	  parameter STRB_W = DATA_W / 8,
9	  parameter ARUSER_W = 1,
10	  parameter M_COUNT = 2,
11	  parameter S_COUNT = 1,
12	  parameter DEFAULT_SLAVE = 0,
13	  parameter [S_COUNT*ADDR_W-1:0] SLAVE_BASE = {S_COUNT{32'h0000_0000}},
14	  parameter [S_COUNT*ADDR_W-1:0] SLAVE_MASK = {S_COUNT{32'h0000_0000}}
15	) (
16	  input clk,
17	  input rst,
18	
19	  input [M_COUNT-1:0] m_arvalid_i,
20	  output [M_COUNT-1:0] m_arready_o,
21	  input [M_COUNT*ADDR_W-1:0] m_araddr_i,
22	  input [M_COUNT*STRB_W-1:0] m_arstrb_i,
23	  input [M_COUNT*ARUSER_W-1:0] m_aruser_i,
24	  input [M_COUNT-1:0] m_read_abort_i,
25	  output [M_COUNT-1:0] m_rvalid_o,
26	  input [M_COUNT-1:0] m_rready_i,
27	  output [M_COUNT*DATA_W-1:0] m_rdata_o,
28	  output [M_COUNT*2-1:0] m_rresp_o,
29	
30	  input [M_COUNT-1:0] m_awvalid_i,
31	  output [M_COUNT-1:0] m_awready_o,
32	  input [M_COUNT*ADDR_W-1:0] m_awaddr_i,
33	  input [M_COUNT-1:0] m_wvalid_i,
34	  output [M_COUNT-1:0] m_wready_o,
35	  input [M_COUNT*DATA_W-1:0] m_wdata_i,
36	  input [M_COUNT*STRB_W-1:0] m_wstrb_i,
37	  output [M_COUNT-1:0] m_bvalid_o,
38	  input [M_COUNT-1:0] m_bready_i,
39	  output [M_COUNT*2-1:0] m_bresp_o,
40	
41	  output [S_COUNT-1:0] s_arvalid_o,
42	  input [S_COUNT-1:0] s_arready_i,
43	  output [S_COUNT*ADDR_W-1:0] s_araddr_o,
44	  output [S_COUNT*STRB_W-1:0] s_arstrb_o,
45	  output [S_COUNT*ARUSER_W-1:0] s_aruser_o,
46	  input [S_COUNT-1:0] s_rvalid_i,
47	  output [S_COUNT-1:0] s_rready_o,
48	  input [S_COUNT*DATA_W-1:0] s_rdata_i,
49	  input [S_COUNT*2-1:0] s_rresp_i,
50	
51	  output [S_COUNT-1:0] s_awvalid_o,
52	  input [S_COUNT-1:0] s_awready_i,
53	  output [S_COUNT*ADDR_W-1:0] s_awaddr_o,
54	  output [S_COUNT-1:0] s_wvalid_o,
55	  input [S_COUNT-1:0] s_wready_i,
56	  output [S_COUNT*DATA_W-1:0] s_wdata_o,
57	  output [S_COUNT*STRB_W-1:0] s_wstrb_o,
58	  input [S_COUNT-1:0] s_bvalid_i,
59	  output [S_COUNT-1:0] s_bready_o,
60	  input [S_COUNT*2-1:0] s_bresp_i
61	);
62	
63	  localparam MASTER_W = (M_COUNT <= 1) ? 1 : $clog2(M_COUNT);
64	  localparam SLAVE_W = (S_COUNT <= 1) ? 1 : $clog2(S_COUNT);
65	
66	  function [ADDR_W-1:0] m_addr_slice;
67	    input [M_COUNT*ADDR_W-1:0] bus;
68	    input [MASTER_W-1:0] idx;
69	    begin
70	      m_addr_slice = bus[idx*ADDR_W +: ADDR_W];
71	    end
72	  endfunction
73	
74	  function [DATA_W-1:0] m_data_slice;
75	    input [M_COUNT*DATA_W-1:0] bus;
76	    input [MASTER_W-1:0] idx;
77	    begin
78	      m_data_slice = bus[idx*DATA_W +: DATA_W];
79	    end
80	  endfunction
81	
82	  function [STRB_W-1:0] m_strb_slice;
83	    input [M_COUNT*STRB_W-1:0] bus;
84	    input [MASTER_W-1:0] idx;
85	    begin
86	      m_strb_slice = bus[idx*STRB_W +: STRB_W];
87	    end
88	  endfunction
89	
90	  function [ARUSER_W-1:0] m_user_slice;
91	    input [M_COUNT*ARUSER_W-1:0] bus;
92	    input [MASTER_W-1:0] idx;
93	    begin
94	      m_user_slice = bus[idx*ARUSER_W +: ARUSER_W];
95	    end
96	  endfunction
97	
98	  function [ADDR_W-1:0] s_base_slice;
99	    input [SLAVE_W-1:0] idx;
100	    begin
101	      s_base_slice = SLAVE_BASE[idx*ADDR_W +: ADDR_W];
102	    end
103	  endfunction
104	
105	  function [ADDR_W-1:0] s_mask_slice;
106	    input [SLAVE_W-1:0] idx;
107	    begin
108	      s_mask_slice = SLAVE_MASK[idx*ADDR_W +: ADDR_W];
109	    end
110	  endfunction
111	
112	  function [MASTER_W-1:0] master_idx;
113	    input [MASTER_W-1:0] idx;
114	    begin
115	      master_idx = idx;
116	    end
117	  endfunction
118	
119	  function [SLAVE_W-1:0] slave_idx;
120	    input [SLAVE_W-1:0] idx;
121	    begin
122	      slave_idx = idx;
123	    end
124	  endfunction
125	
126	  function integer master_int;
127	    input [MASTER_W-1:0] idx;
128	    begin
129	      master_int = idx;
130	    end
131	  endfunction
132	
133	  function [SLAVE_W-1:0] default_slave_idx;
134	    begin
135	      default_slave_idx = (DEFAULT_SLAVE < S_COUNT) ? slave_idx(DEFAULT_SLAVE) :
136	                          {SLAVE_W{1'b0}};
137	    end
138	  endfunction
139	
140	  function [SLAVE_W-1:0] decode_slave;
141	    input [ADDR_W-1:0] addr;
142	    integer k;
143	    reg found;
144	    begin
145	      decode_slave = default_slave_idx();
146	      found = 1'b0;
147	      for (k = 0; k < S_COUNT; k = k + 1) begin
148	        if (!found && ((addr & s_mask_slice(k)) == s_base_slice(k))) begin
149	          decode_slave = slave_idx(k);
150	          found = 1'b1;
151	        end
152	      end
153	    end
154	  endfunction
155	
156	  reg [M_COUNT-1:0] m_arready_r;
157	  reg [M_COUNT-1:0] m_awready_r;
158	  reg [M_COUNT-1:0] m_wready_r;
159	  reg [M_COUNT-1:0] m_rvalid_r;
160	  reg [M_COUNT*DATA_W-1:0] m_rdata_r;
161	  reg [M_COUNT*2-1:0] m_rresp_r;
162	  reg [M_COUNT-1:0] m_bvalid_r;
163	  reg [M_COUNT*2-1:0] m_bresp_r;
164	
165	  reg [S_COUNT-1:0] s_arvalid_r;
166	  reg [S_COUNT*ADDR_W-1:0] s_araddr_r;
167	  reg [S_COUNT*STRB_W-1:0] s_arstrb_r;
168	  reg [S_COUNT*ARUSER_W-1:0] s_aruser_r;
169	  reg [S_COUNT-1:0] s_rready_r;
170	  reg [S_COUNT-1:0] s_awvalid_r;
171	  reg [S_COUNT*ADDR_W-1:0] s_awaddr_r;
172	  reg [S_COUNT-1:0] s_wvalid_r;
173	  reg [S_COUNT*DATA_W-1:0] s_wdata_r;
174	  reg [S_COUNT*STRB_W-1:0] s_wstrb_r;
175	  reg [S_COUNT-1:0] s_bready_r;
176	
177	  reg [M_COUNT-1:0] rd_master_busy_q;
178	  reg [M_COUNT-1:0] rd_resp_valid_q;
179	  reg [DATA_W-1:0] rd_resp_data_q [0:M_COUNT-1];
180	  reg [1:0] rd_resp_resp_q [0:M_COUNT-1];
181	  reg [S_COUNT-1:0] rd_active_q;
182	  reg [S_COUNT-1:0] rd_ar_sent_q;
183	  reg [S_COUNT-1:0] rd_drop_q;
184	  reg [MASTER_W-1:0] rd_owner_q [0:S_COUNT-1];
185	  reg [MASTER_W-1:0] rd_rr_q [0:S_COUNT-1];
186	  reg [ADDR_W-1:0] rd_addr_q [0:S_COUNT-1];
187	  reg [STRB_W-1:0] rd_strb_q [0:S_COUNT-1];
188	  reg [ARUSER_W-1:0] rd_user_q [0:S_COUNT-1];
189	
190	  reg [M_COUNT-1:0] wr_master_busy_q;
191	  reg [M_COUNT-1:0] wr_aw_hold_q;
192	  reg [M_COUNT-1:0] wr_w_hold_q;
193	  reg [ADDR_W-1:0] wr_awaddr_q [0:M_COUNT-1];
194	  reg [SLAVE_W-1:0] wr_awtarget_q [0:M_COUNT-1];
195	  reg [DATA_W-1:0] wr_wdata_q [0:M_COUNT-1];
196	  reg [STRB_W-1:0] wr_wstrb_q [0:M_COUNT-1];
197	
198	  reg [S_COUNT-1:0] wr_active_q;
199	  reg [S_COUNT-1:0] wr_aw_sent_q;
200	  reg [S_COUNT-1:0] wr_w_sent_q;
201	  reg [MASTER_W-1:0] wr_owner_q [0:S_COUNT-1];
202	  reg [MASTER_W-1:0] wr_rr_q [0:S_COUNT-1];
203	  reg [ADDR_W-1:0] wr_addr_q [0:S_COUNT-1];
204	  reg [DATA_W-1:0] wr_data_q [0:S_COUNT-1];
205	  reg [STRB_W-1:0] wr_strb_q [0:S_COUNT-1];
206	
207	  reg [S_COUNT-1:0] rd_grant_valid_r;
208	  reg [MASTER_W-1:0] rd_grant_master_r [0:S_COUNT-1];
209	  reg [S_COUNT-1:0] wr_grant_valid_r;
210	  reg [MASTER_W-1:0] wr_grant_master_r [0:S_COUNT-1];
211	  reg [SLAVE_W-1:0] artarget_decode_r [0:M_COUNT-1];
212	  reg [SLAVE_W-1:0] awtarget_decode_r [0:M_COUNT-1];
213	
214	  assign m_arready_o = m_arready_r;
215	  assign m_awready_o = m_awready_r;
216	  assign m_wready_o = m_wready_r;
217	  assign m_rvalid_o = m_rvalid_r;
218	  assign m_rdata_o = m_rdata_r;
219	  assign m_rresp_o = m_rresp_r;
220	  assign m_bvalid_o = m_bvalid_r;
221	  assign m_bresp_o = m_bresp_r;
222	
223	  assign s_arvalid_o = s_arvalid_r;
224	  assign s_araddr_o = s_araddr_r;
225	  assign s_arstrb_o = s_arstrb_r;
226	  assign s_aruser_o = s_aruser_r;
227	  assign s_rready_o = s_rready_r;
228	  assign s_awvalid_o = s_awvalid_r;
229	  assign s_awaddr_o = s_awaddr_r;
230	  assign s_wvalid_o = s_wvalid_r;
231	  assign s_wdata_o = s_wdata_r;
232	  assign s_wstrb_o = s_wstrb_r;
233	  assign s_bready_o = s_bready_r;
234	
235	  integer s;
236	  integer m;
237	  integer step;
238	  integer cand;
239	  integer owner;
240	
241	  always @(*) begin
242	    m_arready_r = {M_COUNT{1'b0}};
243	    m_awready_r = {M_COUNT{1'b0}};
244	    m_wready_r = {M_COUNT{1'b0}};
245	    m_rvalid_r = {M_COUNT{1'b0}};
246	    m_rdata_r = {M_COUNT*DATA_W{1'b0}};
247	    m_rresp_r = {M_COUNT*2{1'b0}};
248	    m_bvalid_r = {M_COUNT{1'b0}};
249	    m_bresp_r = {M_COUNT*2{1'b0}};
250	
251	    s_arvalid_r = {S_COUNT{1'b0}};
252	    s_araddr_r = {S_COUNT*ADDR_W{1'b0}};
253	    s_arstrb_r = {S_COUNT*STRB_W{1'b0}};
254	    s_aruser_r = {S_COUNT*ARUSER_W{1'b0}};
255	    s_rready_r = {S_COUNT{1'b0}};
256	    s_awvalid_r = {S_COUNT{1'b0}};
257	    s_awaddr_r = {S_COUNT*ADDR_W{1'b0}};
258	    s_wvalid_r = {S_COUNT{1'b0}};
259	    s_wdata_r = {S_COUNT*DATA_W{1'b0}};
260	    s_wstrb_r = {S_COUNT*STRB_W{1'b0}};
261	    s_bready_r = {S_COUNT{1'b0}};
262	
263	    rd_grant_valid_r = {S_COUNT{1'b0}};
264	    wr_grant_valid_r = {S_COUNT{1'b0}};
265	    cand = 0;
266	    owner = 0;
267	    // 每个 master 的目标 slave 只译码一次，再供各 slave 仲裁器复用。
268	    for (m = 0; m < M_COUNT; m = m + 1) begin
269	      artarget_decode_r[m] = decode_slave(m_addr_slice(m_araddr_i, m));
270	      awtarget_decode_r[m] = decode_slave(m_addr_slice(m_awaddr_i, m));
271	    end
272	    for (s = 0; s < S_COUNT; s = s + 1) begin
273	      rd_grant_master_r[s] = {MASTER_W{1'b0}};
274	      wr_grant_master_r[s] = {MASTER_W{1'b0}};
275	    end
276	
277	    for (m = 0; m < M_COUNT; m = m + 1) begin
278	      if (rd_resp_valid_q[m]) begin
279	        m_rvalid_r[m] = 1'b1;
280	        m_rdata_r[m*DATA_W +: DATA_W] = rd_resp_data_q[m];
281	        m_rresp_r[m*2 +: 2] = rd_resp_resp_q[m];
282	      end
283	    end
284	
285	    for (s = 0; s < S_COUNT; s = s + 1) begin
286	      if (!rd_active_q[s]) begin
287	        if (M_COUNT == 2) begin
288	          // 当前 RV64 平台真实使用 IFU/LSU 两个 master；显式两路选择避免综合成可变扫描链。
289	          if (rd_rr_q[s] == master_idx(0)) begin
290	            if (m_arvalid_i[0] && !rd_master_busy_q[0] &&
291	                !m_read_abort_i[0] && (artarget_decode_r[0] == slave_idx(s))) begin
292	              rd_grant_valid_r[s] = 1'b1;
293	              rd_grant_master_r[s] = master_idx(0);
294	              m_arready_r[0] = 1'b1;
295	            end else if (m_arvalid_i[1] && !rd_master_busy_q[1] &&
296	                         !m_read_abort_i[1] && (artarget_decode_r[1] == slave_idx(s))) begin
297	              rd_grant_valid_r[s] = 1'b1;
298	              rd_grant_master_r[s] = master_idx(1);
299	              m_arready_r[1] = 1'b1;
300	            end
301	          end else begin
302	            if (m_arvalid_i[1] && !rd_master_busy_q[1] &&
303	                !m_read_abort_i[1] && (artarget_decode_r[1] == slave_idx(s))) begin
304	              rd_grant_valid_r[s] = 1'b1;
305	              rd_grant_master_r[s] = master_idx(1);
306	              m_arready_r[1] = 1'b1;
307	            end else if (m_arvalid_i[0] && !rd_master_busy_q[0] &&
308	                         !m_read_abort_i[0] && (artarget_decode_r[0] == slave_idx(s))) begin
309	              rd_grant_valid_r[s] = 1'b1;
310	              rd_grant_master_r[s] = master_idx(0);
311	              m_arready_r[0] = 1'b1;
312	            end
313	          end
314	        end else begin
315	          for (step = 0; step < M_COUNT; step = step + 1) begin
316	            cand = master_int(rd_rr_q[s]) + step;
317	            if (cand >= M_COUNT) cand = cand - M_COUNT;
318	            if (!rd_grant_valid_r[s] &&
319	                m_arvalid_i[cand] && !rd_master_busy_q[cand] &&
320	                !m_read_abort_i[cand] &&
321	                (artarget_decode_r[cand] == slave_idx(s))) begin
322	              rd_grant_valid_r[s] = 1'b1;
323	              rd_grant_master_r[s] = master_idx(cand);
324	              m_arready_r[cand] = 1'b1;
325	            end
326	          end
327	        end
328	      end
329	
330	      if (rd_active_q[s] && !rd_ar_sent_q[s]) begin
331	        s_arvalid_r[s] = 1'b1;
332	        s_araddr_r[s*ADDR_W +: ADDR_W] = rd_addr_q[s];
333	        s_arstrb_r[s*STRB_W +: STRB_W] = rd_strb_q[s];
334	        s_aruser_r[s*ARUSER_W +: ARUSER_W] = rd_user_q[s];
335	      end
336	
337	      if (rd_active_q[s] && rd_ar_sent_q[s]) begin
338	        owner = master_int(rd_owner_q[s]);
339	        if (rd_drop_q[s] || m_read_abort_i[owner]) begin
340	          s_rready_r[s] = 1'b1;
341	        end else if (!rd_resp_valid_q[owner]) begin
342	          m_rvalid_r[owner] = s_rvalid_i[s];
343	          m_rdata_r[owner*DATA_W +: DATA_W] = s_rdata_i[s*DATA_W +: DATA_W];
344	          m_rresp_r[owner*2 +: 2] = s_rresp_i[s*2 +: 2];
345	          // 即使 master 暂时不 ready，也先把 response 收进 master-side buffer，
346	          // 释放 slave，避免 IFU response 阻塞 LSU miss 形成结构死锁。
347	          s_rready_r[s] = 1'b1;
348	        end
349	      end
350	    end
351	
352	    for (m = 0; m < M_COUNT; m = m + 1) begin
353	      m_awready_r[m] = !wr_aw_hold_q[m] && !wr_master_busy_q[m];
354	      m_wready_r[m] = !wr_w_hold_q[m] && !wr_master_busy_q[m];
355	    end
356	
357	    for (s = 0; s < S_COUNT; s = s + 1) begin
358	      if (!wr_active_q[s]) begin
359	        if (M_COUNT == 2) begin
360	          // 写通道同样针对真实两 master 路径展开，保留 AW/W hold 后再 grant 的协议边界。
361	          if (wr_rr_q[s] == master_idx(0)) begin
362	            if (wr_aw_hold_q[0] && wr_w_hold_q[0] &&
363	                !wr_master_busy_q[0] && (wr_awtarget_q[0] == slave_idx(s))) begin
364	              wr_grant_valid_r[s] = 1'b1;
365	              wr_grant_master_r[s] = master_idx(0);
366	            end else if (wr_aw_hold_q[1] && wr_w_hold_q[1] &&
367	                         !wr_master_busy_q[1] && (wr_awtarget_q[1] == slave_idx(s))) begin
368	              wr_grant_valid_r[s] = 1'b1;
369	              wr_grant_master_r[s] = master_idx(1);
370	            end
371	          end else begin
372	            if (wr_aw_hold_q[1] && wr_w_hold_q[1] &&
373	                !wr_master_busy_q[1] && (wr_awtarget_q[1] == slave_idx(s))) begin
374	              wr_grant_valid_r[s] = 1'b1;
375	              wr_grant_master_r[s] = master_idx(1);
376	            end else if (wr_aw_hold_q[0] && wr_w_hold_q[0] &&
377	                         !wr_master_busy_q[0] && (wr_awtarget_q[0] == slave_idx(s))) begin
378	              wr_grant_valid_r[s] = 1'b1;
379	              wr_grant_master_r[s] = master_idx(0);
380	            end
381	          end
382	        end else begin
383	          for (step = 0; step < M_COUNT; step = step + 1) begin
384	            cand = master_int(wr_rr_q[s]) + step;
385	            if (cand >= M_COUNT) cand = cand - M_COUNT;
386	            if (!wr_grant_valid_r[s] &&
387	                wr_aw_hold_q[cand] && wr_w_hold_q[cand] &&
388	                !wr_master_busy_q[cand] &&
389	                (wr_awtarget_q[cand] == slave_idx(s))) begin
390	              wr_grant_valid_r[s] = 1'b1;
391	              wr_grant_master_r[s] = master_idx(cand);
392	            end
393	          end
394	        end
395	      end
396	
397	      if (wr_active_q[s] && !wr_aw_sent_q[s]) begin
398	        s_awvalid_r[s] = 1'b1;
399	        s_awaddr_r[s*ADDR_W +: ADDR_W] = wr_addr_q[s];
400	      end
401	
402	      if (wr_active_q[s] && !wr_w_sent_q[s]) begin
403	        s_wvalid_r[s] = 1'b1;
404	        s_wdata_r[s*DATA_W +: DATA_W] = wr_data_q[s];
405	        s_wstrb_r[s*STRB_W +: STRB_W] = wr_strb_q[s];
406	      end
407	
408	      if (wr_active_q[s] && wr_aw_sent_q[s] && wr_w_sent_q[s]) begin
409	        owner = master_int(wr_owner_q[s]);
410	        m_bvalid_r[owner] = s_bvalid_i[s];
411	        m_bresp_r[owner*2 +: 2] = s_bresp_i[s*2 +: 2];
412	        s_bready_r[s] = m_bready_i[owner];
413	      end
414	    end
415	  end
416	
417	  always @(posedge clk) begin
418	    if (rst) begin
419	      rd_master_busy_q <= {M_COUNT{1'b0}};
420	      rd_resp_valid_q <= {M_COUNT{1'b0}};
421	      wr_master_busy_q <= {M_COUNT{1'b0}};
422	      wr_aw_hold_q <= {M_COUNT{1'b0}};
423	      wr_w_hold_q <= {M_COUNT{1'b0}};
424	      rd_active_q <= {S_COUNT{1'b0}};
425	      rd_ar_sent_q <= {S_COUNT{1'b0}};
426	      rd_drop_q <= {S_COUNT{1'b0}};
427	      wr_active_q <= {S_COUNT{1'b0}};
428	      wr_aw_sent_q <= {S_COUNT{1'b0}};
429	      wr_w_sent_q <= {S_COUNT{1'b0}};
430	      for (m = 0; m < M_COUNT; m = m + 1) begin
431	        rd_resp_data_q[m] <= {DATA_W{1'b0}};
432	        rd_resp_resp_q[m] <= 2'b00;
433	        wr_awaddr_q[m] <= {ADDR_W{1'b0}};
434	        wr_awtarget_q[m] <= {SLAVE_W{1'b0}};
435	        wr_wdata_q[m] <= {DATA_W{1'b0}};
436	        wr_wstrb_q[m] <= {STRB_W{1'b0}};
437	      end
438	      for (s = 0; s < S_COUNT; s = s + 1) begin
439	        rd_owner_q[s] <= {MASTER_W{1'b0}};
440	        rd_rr_q[s] <= {MASTER_W{1'b0}};
441	        rd_addr_q[s] <= {ADDR_W{1'b0}};
442	        rd_strb_q[s] <= {STRB_W{1'b0}};
443	        rd_user_q[s] <= {ARUSER_W{1'b0}};
444	        wr_owner_q[s] <= {MASTER_W{1'b0}};
445	        wr_rr_q[s] <= {MASTER_W{1'b0}};
446	        wr_addr_q[s] <= {ADDR_W{1'b0}};
447	        wr_data_q[s] <= {DATA_W{1'b0}};
448	        wr_strb_q[s] <= {STRB_W{1'b0}};
449	      end
450	    end else begin
451	      for (m = 0; m < M_COUNT; m = m + 1) begin
452	        if (rd_resp_valid_q[m] && m_rready_i[m]) begin
453	          rd_resp_valid_q[m] <= 1'b0;
454	          rd_master_busy_q[m] <= 1'b0;
455	        end
456	
457	        if (m_read_abort_i[m] && rd_resp_valid_q[m]) begin
458	          rd_resp_valid_q[m] <= 1'b0;
459	          rd_master_busy_q[m] <= 1'b0;
460	        end
461	      end
462	
463	      for (s = 0; s < S_COUNT; s = s + 1) begin
464	        if (rd_active_q[s] && !rd_ar_sent_q[s] &&
465	            s_arvalid_r[s] && s_arready_i[s]) begin
466	          rd_ar_sent_q[s] <= 1'b1;
467	        end
468	
469	        if (rd_active_q[s] && rd_ar_sent_q[s] &&
470	            s_rvalid_i[s] && s_rready_r[s]) begin
471	          rd_active_q[s] <= 1'b0;
472	          rd_ar_sent_q[s] <= 1'b0;
473	          rd_drop_q[s] <= 1'b0;
474	          if (rd_drop_q[s] || m_read_abort_i[master_int(rd_owner_q[s])]) begin
475	            rd_master_busy_q[master_int(rd_owner_q[s])] <= 1'b0;
476	          end else if (m_rready_i[master_int(rd_owner_q[s])]) begin
477	            rd_master_busy_q[master_int(rd_owner_q[s])] <= 1'b0;
478	          end else begin
479	            rd_resp_valid_q[master_int(rd_owner_q[s])] <= 1'b1;
480	            rd_resp_data_q[master_int(rd_owner_q[s])] <= s_rdata_i[s*DATA_W +: DATA_W];
481	            rd_resp_resp_q[master_int(rd_owner_q[s])] <= s_rresp_i[s*2 +: 2];
482	          end
483	        end else if (rd_active_q[s] &&
484	                     m_read_abort_i[master_int(rd_owner_q[s])]) begin
485	          if (rd_ar_sent_q[s] || (s_arvalid_r[s] && s_arready_i[s])) begin
486	            // AR 已经在当前或更早周期被 slave 接收，不能凭空取消；
487	            // 保持 master busy，等 R 返回后按 drop 丢弃，避免留下 orphan response。
488	            rd_ar_sent_q[s] <= 1'b1;
489	            rd_drop_q[s] <= 1'b1;
490	          end else begin
491	            rd_active_q[s] <= 1'b0;
492	            rd_ar_sent_q[s] <= 1'b0;
493	            rd_drop_q[s] <= 1'b0;
494	            rd_master_busy_q[master_int(rd_owner_q[s])] <= 1'b0;
495	          end
496	        end
497	
498	        if (!rd_active_q[s] && rd_grant_valid_r[s]) begin
499	          rd_active_q[s] <= 1'b1;
500	          rd_ar_sent_q[s] <= 1'b0;
501	          rd_drop_q[s] <= 1'b0;
502	          rd_owner_q[s] <= rd_grant_master_r[s];
503	          rd_addr_q[s] <= m_addr_slice(m_araddr_i, master_int(rd_grant_master_r[s]));
504	          rd_strb_q[s] <= m_strb_slice(m_arstrb_i, master_int(rd_grant_master_r[s]));
505	          rd_user_q[s] <= m_user_slice(m_aruser_i, master_int(rd_grant_master_r[s]));
506	          rd_master_busy_q[master_int(rd_grant_master_r[s])] <= 1'b1;
507	          rd_rr_q[s] <= (master_int(rd_grant_master_r[s]) == (M_COUNT - 1)) ?
508	                         {MASTER_W{1'b0}} :
509	                         master_idx(master_int(rd_grant_master_r[s]) + 1);
510	        end
511	      end
512	
513	      for (m = 0; m < M_COUNT; m = m + 1) begin
514	        if (m_awvalid_i[m] && m_awready_r[m]) begin
515	          wr_aw_hold_q[m] <= 1'b1;
516	          wr_awaddr_q[m] <= m_addr_slice(m_awaddr_i, m);
517	          wr_awtarget_q[m] <= awtarget_decode_r[m];
518	        end
519	
520	        if (m_wvalid_i[m] && m_wready_r[m]) begin
521	          wr_w_hold_q[m] <= 1'b1;
522	          wr_wdata_q[m] <= m_data_slice(m_wdata_i, m);
523	          wr_wstrb_q[m] <= m_strb_slice(m_wstrb_i, m);
524	        end
525	      end
526	
527	      for (s = 0; s < S_COUNT; s = s + 1) begin
528	        if (wr_active_q[s] && !wr_aw_sent_q[s] &&
529	            s_awvalid_r[s] && s_awready_i[s]) begin
530	          wr_aw_sent_q[s] <= 1'b1;
531	        end
532	
533	        if (wr_active_q[s] && !wr_w_sent_q[s] &&
534	            s_wvalid_r[s] && s_wready_i[s]) begin
535	          wr_w_sent_q[s] <= 1'b1;
536	        end
537	
538	        if (wr_active_q[s] && wr_aw_sent_q[s] && wr_w_sent_q[s] &&
539	            s_bvalid_i[s] && s_bready_r[s]) begin
540	          wr_active_q[s] <= 1'b0;
541	          wr_aw_sent_q[s] <= 1'b0;
542	          wr_w_sent_q[s] <= 1'b0;
543	          wr_master_busy_q[master_int(wr_owner_q[s])] <= 1'b0;
544	        end
545	
546	        if (!wr_active_q[s] && wr_grant_valid_r[s]) begin
547	          wr_active_q[s] <= 1'b1;
548	          wr_aw_sent_q[s] <= 1'b0;
549	          wr_w_sent_q[s] <= 1'b0;
550	          wr_owner_q[s] <= wr_grant_master_r[s];
551	          wr_addr_q[s] <= wr_awaddr_q[master_int(wr_grant_master_r[s])];
552	          wr_data_q[s] <= wr_wdata_q[master_int(wr_grant_master_r[s])];
553	          wr_strb_q[s] <= wr_wstrb_q[master_int(wr_grant_master_r[s])];
554	          wr_aw_hold_q[master_int(wr_grant_master_r[s])] <= 1'b0;
555	          wr_w_hold_q[master_int(wr_grant_master_r[s])] <= 1'b0;
556	          wr_master_busy_q[master_int(wr_grant_master_r[s])] <= 1'b1;
557	          wr_rr_q[s] <= (master_int(wr_grant_master_r[s]) == (M_COUNT - 1)) ?
558	                         {MASTER_W{1'b0}} :
559	                         master_idx(master_int(wr_grant_master_r[s]) + 1);
560	        end
561	      end
562	    end
563	  end
564	
565	endmodule
