1	`include "define.v"
2	
3	// NPC 总线壳：把当前 IFU/LSU 两个 single-beat AXI-like master
4	// 打包后交给通用 crossbar。后续加设备只扩展 slave 侧地址表和端口，
5	// 不再把设备译码塞回 NpcCore 或 NpcSimTop。
6	module NpcAxiBus #(
7	  parameter S_COUNT = 1,
8	  parameter DEFAULT_SLAVE = 0,
9	  parameter [S_COUNT*`XLEN-1:0] SLAVE_BASE = {S_COUNT{32'h0000_0000}},
10	  parameter [S_COUNT*`XLEN-1:0] SLAVE_MASK = {S_COUNT{32'h0000_0000}}
11	) (
12	  input clk,
13	  input rst,
14	
15	  input ifu_axi_arvalid_i,
16	  output ifu_axi_arready_o,
17	  input [`XLEN-1:0] ifu_axi_araddr_i,
18	  input ifu_axi_abort_i,
19	  output ifu_axi_rvalid_o,
20	  input ifu_axi_rready_i,
21	  output [`XLEN-1:0] ifu_axi_rdata_o,
22	  output [1:0] ifu_axi_rresp_o,
23	  // HW-managed A 更新：取指桥写通道(写回 PTE 置 A 位), 接 xbar 现成 M_IFU 写 master 口。
24	  input ifu_axi_awvalid_i,
25	  output ifu_axi_awready_o,
26	  input [`XLEN-1:0] ifu_axi_awaddr_i,
27	  input ifu_axi_wvalid_i,
28	  output ifu_axi_wready_o,
29	  input [`XLEN-1:0] ifu_axi_wdata_i,
30	  input [`STRB_W-1:0] ifu_axi_wstrb_i,
31	  output ifu_axi_bvalid_o,
32	  input ifu_axi_bready_i,
33	  output [1:0] ifu_axi_bresp_o,
34	
35	  input lsu_axi_arvalid_i,
36	  output lsu_axi_arready_o,
37	  input [`XLEN-1:0] lsu_axi_araddr_i,
38	  input [`STRB_W-1:0] lsu_axi_arstrb_i,
39	  input lsu_axi_abort_i,
40	  output lsu_axi_rvalid_o,
41	  input lsu_axi_rready_i,
42	  output [`XLEN-1:0] lsu_axi_rdata_o,
43	  output [1:0] lsu_axi_rresp_o,
44	  input lsu_axi_awvalid_i,
45	  output lsu_axi_awready_o,
46	  input [`XLEN-1:0] lsu_axi_awaddr_i,
47	  input lsu_axi_wvalid_i,
48	  output lsu_axi_wready_o,
49	  input [`XLEN-1:0] lsu_axi_wdata_i,
50	  input [`STRB_W-1:0] lsu_axi_wstrb_i,
51	  output lsu_axi_bvalid_o,
52	  input lsu_axi_bready_i,
53	  output [1:0] lsu_axi_bresp_o,
54	
55	  output [S_COUNT-1:0] s_axi_arvalid_o,
56	  input [S_COUNT-1:0] s_axi_arready_i,
57	  output [S_COUNT*`XLEN-1:0] s_axi_araddr_o,
58	  output [S_COUNT*`STRB_W-1:0] s_axi_arstrb_o,
59	  output [S_COUNT-1:0] s_axi_aruser_o,
60	  input [S_COUNT-1:0] s_axi_rvalid_i,
61	  output [S_COUNT-1:0] s_axi_rready_o,
62	  input [S_COUNT*`XLEN-1:0] s_axi_rdata_i,
63	  input [S_COUNT*2-1:0] s_axi_rresp_i,
64	
65	  output [S_COUNT-1:0] s_axi_awvalid_o,
66	  input [S_COUNT-1:0] s_axi_awready_i,
67	  output [S_COUNT*`XLEN-1:0] s_axi_awaddr_o,
68	  output [S_COUNT-1:0] s_axi_wvalid_o,
69	  input [S_COUNT-1:0] s_axi_wready_i,
70	  output [S_COUNT*`XLEN-1:0] s_axi_wdata_o,
71	  output [S_COUNT*`STRB_W-1:0] s_axi_wstrb_o,
72	  input [S_COUNT-1:0] s_axi_bvalid_i,
73	  output [S_COUNT-1:0] s_axi_bready_o,
74	  input [S_COUNT*2-1:0] s_axi_bresp_i
75	);
76	
77	  localparam M_COUNT = 2;
78	  localparam M_IFU = 0;
79	  localparam M_LSU = 1;
80	  localparam ARUSER_IFETCH = 1'b0;
81	  localparam ARUSER_LOAD = 1'b1;
82	
83	  wire [M_COUNT-1:0] m_arvalid_w;
84	  wire [M_COUNT-1:0] m_arready_w;
85	  wire [M_COUNT*`XLEN-1:0] m_araddr_w;
86	  wire [M_COUNT*`STRB_W-1:0] m_arstrb_w;
87	  wire [M_COUNT-1:0] m_aruser_w;
88	  wire [M_COUNT-1:0] m_read_abort_w;
89	  wire [M_COUNT-1:0] m_rvalid_w;
90	  wire [M_COUNT-1:0] m_rready_w;
91	  wire [M_COUNT*`XLEN-1:0] m_rdata_w;
92	  wire [M_COUNT*2-1:0] m_rresp_w;
93	
94	  wire [M_COUNT-1:0] m_awvalid_w;
95	  wire [M_COUNT-1:0] m_awready_w;
96	  wire [M_COUNT*`XLEN-1:0] m_awaddr_w;
97	  wire [M_COUNT-1:0] m_wvalid_w;
98	  wire [M_COUNT-1:0] m_wready_w;
99	  wire [M_COUNT*`XLEN-1:0] m_wdata_w;
100	  wire [M_COUNT*`STRB_W-1:0] m_wstrb_w;
101	  wire [M_COUNT-1:0] m_bvalid_w;
102	  wire [M_COUNT-1:0] m_bready_w;
103	  wire [M_COUNT*2-1:0] m_bresp_w;
104	
105	  assign m_arvalid_w[M_IFU] = ifu_axi_arvalid_i;
106	  assign m_arvalid_w[M_LSU] = lsu_axi_arvalid_i;
107	  assign m_araddr_w[M_IFU*`XLEN +: `XLEN] = ifu_axi_araddr_i;
108	  assign m_araddr_w[M_LSU*`XLEN +: `XLEN] = lsu_axi_araddr_i;
109	  assign m_arstrb_w[M_IFU*`STRB_W +: `STRB_W] = {`STRB_W{1'b1}};
110	  assign m_arstrb_w[M_LSU*`STRB_W +: `STRB_W] = lsu_axi_arstrb_i;
111	  assign m_aruser_w[M_IFU] = ARUSER_IFETCH;
112	  assign m_aruser_w[M_LSU] = ARUSER_LOAD;
113	  assign m_read_abort_w[M_IFU] = ifu_axi_abort_i;
114	  assign m_read_abort_w[M_LSU] = lsu_axi_abort_i;
115	  assign m_rready_w[M_IFU] = ifu_axi_rready_i;
116	  assign m_rready_w[M_LSU] = lsu_axi_rready_i;
117	
118	  assign ifu_axi_arready_o = m_arready_w[M_IFU];
119	  assign lsu_axi_arready_o = m_arready_w[M_LSU];
120	  assign ifu_axi_rvalid_o = m_rvalid_w[M_IFU];
121	  assign lsu_axi_rvalid_o = m_rvalid_w[M_LSU];
122	  assign ifu_axi_rdata_o = m_rdata_w[M_IFU*`XLEN +: `XLEN];
123	  assign lsu_axi_rdata_o = m_rdata_w[M_LSU*`XLEN +: `XLEN];
124	  assign ifu_axi_rresp_o = m_rresp_w[M_IFU*2 +: 2];
125	  assign lsu_axi_rresp_o = m_rresp_w[M_LSU*2 +: 2];
126	
127	  assign m_awvalid_w[M_IFU] = ifu_axi_awvalid_i;
128	  assign m_awvalid_w[M_LSU] = lsu_axi_awvalid_i;
129	  assign m_awaddr_w[M_IFU*`XLEN +: `XLEN] = ifu_axi_awaddr_i;
130	  assign m_awaddr_w[M_LSU*`XLEN +: `XLEN] = lsu_axi_awaddr_i;
131	  assign m_wvalid_w[M_IFU] = ifu_axi_wvalid_i;
132	  assign m_wvalid_w[M_LSU] = lsu_axi_wvalid_i;
133	  assign m_wdata_w[M_IFU*`XLEN +: `XLEN] = ifu_axi_wdata_i;
134	  assign m_wdata_w[M_LSU*`XLEN +: `XLEN] = lsu_axi_wdata_i;
135	  assign m_wstrb_w[M_IFU*`STRB_W +: `STRB_W] = ifu_axi_wstrb_i;
136	  assign m_wstrb_w[M_LSU*`STRB_W +: `STRB_W] = lsu_axi_wstrb_i;
137	  assign m_bready_w[M_IFU] = ifu_axi_bready_i;
138	  assign m_bready_w[M_LSU] = lsu_axi_bready_i;
139	
140	  assign ifu_axi_awready_o = m_awready_w[M_IFU];
