1	`include "define.v"
2	
3	// 仿真专用 AXI-like slave：把 crossbar slave 端请求桥接到宿主 PMEM/MMIO。
4	// 该模块只属于 Verilator 顶层，不进入综合路径中的真实外设实现。
5	import "DPI-C" task npc_ifetch(
6	  input longint unsigned addr,
7	  output longint unsigned data,
8	  output bit error
9	);
10	
11	import "DPI-C" task npc_mem_read(
12	  input longint unsigned addr,
13	  output longint unsigned data,
14	  output bit error
15	);
16	
17	import "DPI-C" task npc_mem_write(
18	  input longint unsigned addr,
19	  input longint unsigned data,
20	  input longint unsigned mask,
21	  output bit error
22	);
23	
24	module AxiDpiSlave (
25	  input logic clk,
26	  input logic rst,
27	
28	  input logic s_axi_arvalid_i,
29	  output logic s_axi_arready_o,
30	  input logic [`XLEN-1:0] s_axi_araddr_i,
31	  input logic s_axi_aruser_i,
32	  output logic s_axi_rvalid_o,
33	  input logic s_axi_rready_i,
34	  output logic [`XLEN-1:0] s_axi_rdata_o,
35	  output logic [1:0] s_axi_rresp_o,
36	
37	  input logic s_axi_awvalid_i,
38	  output logic s_axi_awready_o,
39	  input logic [`XLEN-1:0] s_axi_awaddr_i,
40	  input logic s_axi_wvalid_i,
41	  output logic s_axi_wready_o,
42	  input logic [`XLEN-1:0] s_axi_wdata_i,
43	  input logic [`STRB_W-1:0] s_axi_wstrb_i,
44	  output logic s_axi_bvalid_o,
45	  input logic s_axi_bready_i,
46	  output logic [1:0] s_axi_bresp_o
47	);
48	
49	  logic [`XLEN-1:0] awaddr_q;
50	  logic aw_valid_q;
51	  logic [`XLEN-1:0] wdata_q;
52	  logic [`STRB_W-1:0] wstrb_q;
53	  logic w_valid_q;
54	
55	  wire ar_fire_w = s_axi_arvalid_i && s_axi_arready_o;
56	  wire aw_fire_w = s_axi_awvalid_i && s_axi_awready_o;
57	  wire w_fire_w = s_axi_wvalid_i && s_axi_wready_o;
58	  wire write_complete_w = !s_axi_bvalid_o &&
59	                          (aw_valid_q || aw_fire_w) &&
60	                          (w_valid_q || w_fire_w);
61	
62	  assign s_axi_arready_o = !s_axi_rvalid_o;
63	  assign s_axi_awready_o = !aw_valid_q && !s_axi_bvalid_o;
64	  assign s_axi_wready_o = !w_valid_q && !s_axi_bvalid_o;
65	
66	  always_ff @(posedge clk) begin
67	    longint unsigned bus_data_v;
68	    longint unsigned write_addr_v;
69	    longint unsigned write_data_v;
70	    longint unsigned write_mask_v;
71	    bit bus_error_v;
72	
73	    if (rst) begin
74	      s_axi_rvalid_o <= 1'b0;
75	      s_axi_rdata_o <= {`XLEN{1'b0}};
76	      s_axi_rresp_o <= 2'b00;
77	      s_axi_bvalid_o <= 1'b0;
78	      s_axi_bresp_o <= 2'b00;
79	      awaddr_q <= {`XLEN{1'b0}};
80	      aw_valid_q <= 1'b0;
81	      wdata_q <= {`XLEN{1'b0}};
82	      wstrb_q <= {`STRB_W{1'b0}};
83	      w_valid_q <= 1'b0;
84	    end else begin
85	      if (s_axi_rvalid_o && s_axi_rready_i) begin
86	        s_axi_rvalid_o <= 1'b0;
87	      end
88	
89	      if (s_axi_bvalid_o && s_axi_bready_i) begin
90	        s_axi_bvalid_o <= 1'b0;
91	      end
92	
93	      if (ar_fire_w) begin
94	        if (s_axi_aruser_i == 1'b0) begin
95	          npc_ifetch(s_axi_araddr_i, bus_data_v, bus_error_v);
96	        end else begin
97	          npc_mem_read(s_axi_araddr_i, bus_data_v, bus_error_v);
98	        end
99	        s_axi_rvalid_o <= 1'b1;
100	        s_axi_rdata_o <= bus_data_v[`XLEN-1:0];
101	        s_axi_rresp_o <= bus_error_v ? 2'b10 : 2'b00;
102	      end
103	
104	      if (aw_fire_w) begin
105	        awaddr_q <= s_axi_awaddr_i;
106	        aw_valid_q <= 1'b1;
107	      end
108	
109	      if (w_fire_w) begin
110	        wdata_q <= s_axi_wdata_i;
111	        wstrb_q <= s_axi_wstrb_i;
112	        w_valid_q <= 1'b1;
113	      end
114	
115	      if (write_complete_w) begin
116	        write_addr_v = aw_fire_w ? s_axi_awaddr_i : awaddr_q;
117	        write_data_v = w_fire_w ? s_axi_wdata_i : wdata_q;
118	        write_mask_v = {{(64-`STRB_W){1'b0}}, (w_fire_w ? s_axi_wstrb_i : wstrb_q)};
119	        npc_mem_write(write_addr_v, write_data_v, write_mask_v, bus_error_v);
120	        s_axi_bvalid_o <= 1'b1;
121	        s_axi_bresp_o <= bus_error_v ? 2'b10 : 2'b00;
122	        aw_valid_q <= 1'b0;
123	        w_valid_q <= 1'b0;
124	      end
125	    end
126	  end
127	
128	endmodule
