715	                  resp1_q <= RESP_ACCESS_FAULT;
716	                  state_q <= S_AR0;
717	                end else begin
718	                  resp0_q <= RESP_ACCESS_FAULT;
719	                  resp1_q <= RESP_ACCESS_FAULT;
720	                  state_q <= S_RESP;
721	                end
722	              // HW A: 真权限+PMP 全过但 A=0 → 写回 PTE|A 后 re-walk 本级(读回 A=1 续原取指)。
723	              // walk_ppn_q/walk_level_q 保持不变 → walk_pte_addr_w 仍指向本 leaf PTE。
724	              // 置 A 后真 fault 已排除, 故不会与 fault 竞争(fault 分支在前, 优先)。
725	              end else if (exec_ad_update_needed(ifu_axi_rdata_i)) begin
726	                ad_pte_q <= ifu_axi_rdata_i | PTE_A_BIT;
727	                aw_done_q <= 1'b0;
728	                w_done_q <= 1'b0;
729	                state_q <= S_AD_UPDATE;
730	              end else begin
731	                if (walk_second_q) begin
732	                paddr1_q <= leaf_paddr(ifu_axi_rdata_i,
733	                                       pc_second_page_vaddr_w,
734	                                       walk_level_q);
735	                resp1_q <= RESP_OK;
736	                state_q <= S_AR0;
737	                end else begin
738	                paddr0_q <= leaf_paddr(ifu_axi_rdata_i, pc_q, walk_level_q);
739	                resp0_q <= RESP_OK;
740	                if (same_fetch_page_w) begin
741	                  paddr1_q <= leaf_paddr(ifu_axi_rdata_i, pc_q,
742	                                         walk_level_q) + 64'd4;
743	                  resp1_q <= walk_leaf_exec1_pmp_fault_w ?
744	                             RESP_ACCESS_FAULT : RESP_OK;
745	                  state_q <= S_AR0;
746	                end else if (canonical_sv39(pc_second_page_vaddr_w)) begin
747	                  walk_second_q <= 1'b1;
748	                  walk_level_q <= 2'd2;
749	                  walk_ppn_q <= req_satp_q[43:0];
750	                  state_q <= S_WALK_AR;
751	                end else begin
752	                  resp1_q <= RESP_PAGE_FAULT;
753	                  state_q <= S_AR0;
754	                end
755	              end
756	              end
757	            end else begin
758	              walk_ppn_q <= ifu_axi_rdata_i[53:10];
759	              walk_level_q <= walk_level_q - 2'd1;
760	              state_q <= S_WALK_AR;
761	            end
762	          end
763	        end
764	
765	        S_AR0: begin
766	          if (ifu_axi_arready_i) begin
767	            state_q <= S_R0;
768	          end
769	        end
770	
771	        S_R0: begin
772	          if (ifu_axi_rvalid_i) begin
773	            first_beat_q <= ifu_axi_rdata_i;
774	            inst0_q <= fetch_beat_inst0_w;
775	            inst1_q <= fetch_beat_inst1_w;
776	            if (ifu_axi_rresp_i != RESP_OK) begin
777	              resp0_q <= RESP_ACCESS_FAULT;
778	              resp1_q <= RESP_ACCESS_FAULT;
779	              state_q <= S_RESP;
780	            end else if (packet_cross_page_q && (resp1_q == RESP_OK)) begin
781	              state_q <= S_AR1;
782	            end else begin
783	              if (packet_cross_page_q && first_inst_cross_page_w &&
784	                  (resp1_q != RESP_OK)) begin
785	                resp0_q <= resp1_q;
786	              end
787	              state_q <= S_RESP;
788	            end
789	          end
790	        end
791	
792	        S_AR1: begin
793	          if (ifu_axi_arready_i) begin
794	            state_q <= S_R1;
795	          end
796	        end
797	
798	        S_R1: begin
799	          if (ifu_axi_rvalid_i) begin
800	            inst0_q <= merged_cross_packet_w[`INST_W-1:0];
801	            inst1_q <= merged_cross_packet_w[`XLEN-1:`INST_W];
802	            if (first_inst_cross_page_w && (ifu_axi_rresp_i != RESP_OK)) begin
803	              resp0_q <= RESP_ACCESS_FAULT;
804	            end
805	            resp1_q <= (ifu_axi_rresp_i == RESP_OK) ? resp1_q :
806	                       RESP_ACCESS_FAULT;
807	            state_q <= S_RESP;
808	          end
809	        end
810	
811	        S_AD_UPDATE: begin
812	          // 写回 PTE|A: 完成 AW/W + 吸收 B 后 re-walk 本级(walk_ppn_q/walk_level_q 未改,
813	          // 重读同一 leaf PTE 此时 A=1 → exec_ad_update_needed=0 → 走正常 leaf-OK 续流)。
814	          // mmu_flush 会打回 S_IDLE 丢写(A 更新幂等, re-fetch 重做), 不损正确性。
815	          if (ifu_ad_aw_fire_w) aw_done_q <= 1'b1;
816	          if (ifu_ad_w_fire_w) w_done_q <= 1'b1;
817	          if ((aw_done_q || ifu_ad_aw_fire_w) &&
818	              (w_done_q || ifu_ad_w_fire_w) && ifu_axi_bvalid_i) begin
819	            aw_done_q <= 1'b0;
820	            w_done_q <= 1'b0;
821	            if (ifu_axi_bresp_i == RESP_OK) begin
822	              state_q <= S_WALK_AR;
823	            end else begin
824	              // A 写失败(极罕见: PTE 落不可写区) → 取指 access fault, 避免 A=0 无限重试。
825	              if (walk_second_q) begin
826	                resp1_q <= RESP_ACCESS_FAULT;
827	                state_q <= S_AR0;
828	              end else begin
829	                resp0_q <= RESP_ACCESS_FAULT;
830	                resp1_q <= RESP_ACCESS_FAULT;
831	                state_q <= S_RESP;
832	              end
833	            end
834	          end
835	        end
836	
837	        S_RESP: begin
838	          // back-to-back accept: 与 S_IDLE 同为 fire 拍, 只锁存请求并进 S_LOOKUP
839	          // (fetch_req_fire_w = valid && S_RESP && rsp_ready, 同拍发射 lookup_en_i)。
840	          if (fetch_rsp_ready_i) begin
841	            if (fetch_req_valid_i) begin
842	              pc_q <= fetch_req_pc_i;
843	              paddr0_q <= fetch_req_pc_i;
844	              paddr1_q <= req_cross_fetch_page_w ? req_second_page_vaddr_w :
845	                                                     (fetch_req_pc_i + 64'd4);
846	              packet_cross_page_q <= req_cross_fetch_page_w;
847	              packet_first_bytes_q <= req_first_page_bytes_w;
848	              first_beat_q <= {`XLEN{1'b0}};
849	              inst0_q <= {`INST_W{1'b0}};
850	              inst1_q <= {`INST_W{1'b0}};
851	              resp0_q <= RESP_OK;
852	              resp1_q <= RESP_OK;
853	              paging_q <= req_paging_w;
854	              req_priv_q <= priv_mode_i;
855	              req_satp_q <= satp_i;
856	              req_svpbmt_en_q <= svpbmt_en_i;
857	              state_q <= S_LOOKUP;
858	            end else begin
859	              state_q <= S_IDLE;
860	            end
861	          end
862	        end
863	
864	        default: begin
865	          state_q <= S_IDLE;
866	        end
867	      endcase
868	    end
869	  end
870	
871	endmodule
