20	  //   probe: write 探测——翻译+PMP 走完后不写内存, PA 经 rsp_rdata 回传(fault 路径复用);
21	  //   pretrans: 地址已是 PA(SQ drain 落存)——跳过翻译与 PMP(probe 拍已查);
22	  //   nokill: 事务不可被 flush 丢弃(已退休 store 的落存写必达)。
23	  // 三位全 0 时本模块行为与旧版逐位一致。
24	  input mem0_req_probe_i,
25	  input mem0_req_pretrans_i,
26	  input mem0_req_nokill_i,
27	  input [`XLEN-1:0] mem0_req_addr_i,
28	  input [`XLEN-1:0] mem0_req_wdata_i,
29	  input [`STRB_W-1:0] mem0_req_wstrb_i,
30	  output mem0_rsp_valid_o,
31	  input mem0_rsp_ready_i,
32	  output [`XLEN-1:0] mem0_rsp_rdata_o,
33	  output mem0_rsp_error_o,
34	  output mem0_rsp_page_fault_o,
35	  // 当前特权/satp 上下文下数据访问是否经 Sv39 翻译(供后端 load-vs-SQ 判定选 blind 模式)
36	  output translate_active_o,
37	
