39	  input lsu_axi_arready_i,
40	  output [`XLEN-1:0] lsu_axi_araddr_o,
41	  output [`STRB_W-1:0] lsu_axi_arstrb_o,
42	  input lsu_axi_rvalid_i,
43	  output lsu_axi_rready_o,
44	  input [`XLEN-1:0] lsu_axi_rdata_i,
45	  input [1:0] lsu_axi_rresp_i,
46	  output lsu_axi_awvalid_o,
47	  input lsu_axi_awready_i,
48	  output [`XLEN-1:0] lsu_axi_awaddr_o,
49	  output lsu_axi_wvalid_o,
50	  input lsu_axi_wready_i,
51	  output [`XLEN-1:0] lsu_axi_wdata_o,
52	  output [`STRB_W-1:0] lsu_axi_wstrb_o,
53	  input lsu_axi_bvalid_i,
54	  output lsu_axi_bready_o,
55	  input [1:0] lsu_axi_bresp_i
56	);
57	
58	  localparam [3:0] S_IDLE = 4'd0;
59	  localparam [3:0] S_WALK_AR = 4'd1;
60	  localparam [3:0] S_WALK_R = 4'd2;
61	  localparam [3:0] S_READ_ADDR = 4'd3;
62	  localparam [3:0] S_READ_DATA = 4'd4;
63	  localparam [3:0] S_WRITE_REQ = 4'd5;
64	  localparam [3:0] S_WRITE_RESP = 4'd6;
65	  localparam [3:0] S_RESP = 4'd7;
66	  localparam [3:0] S_AD_UPDATE = 4'd8;   // HW A/D: 写回 leaf PTE 置 A(D)位, 再续原访问
67	  // 【SRAM 同步读】dcache 判决态: 上拍已发 dcache 单口读(发射拍), 本拍 SRAM rdata
68	  // 有效, 判 hit(→S_RESP)/miss(当拍发 AR)。load hit 1→2 拍是一期接受的代价。
69	  localparam [3:0] S_LOOKUP = 4'd9;
70	  localparam [`XLEN-1:0] PTE_A_BIT = {{(`XLEN-7){1'b0}}, 7'h40};  // bit 6 (Accessed)
71	  localparam [`XLEN-1:0] PTE_D_BIT = {{(`XLEN-8){1'b0}}, 8'h80};  // bit 7 (Dirty)
72	  // 【LSQ Phase2+3】8KB(2^10×8B)直映对 CoreMark 工作集 miss 率 47.6%——
73	  // 容量拉到 32KB(2^12), miss 流转 hit 流(hit 已 1 req/拍 back-to-back)。
74	  localparam DTLB_INDEX_W = 6;
75	
76	  reg [3:0] state_q;
77	  reg write_q;
78	  reg paging_q;
79	  reg [1:0] access_priv_q;
80	  reg access_svpbmt_en_q;
81	  reg [1:0] walk_level_q;
82	  reg [43:0] walk_ppn_q;
83	  reg [`XLEN-1:0] addr_q;
84	  reg [`XLEN-1:0] paddr_q;
85	  reg [`XLEN-1:0] ad_pte_q;    // HW A/D: 置位后的 leaf PTE(供 S_AD_UPDATE 写 + TLB 填)
86	  reg [`XLEN-1:0] wdata_q;
87	  reg [`STRB_W-1:0] wstrb_q;
88	  reg [`XLEN-1:0] rsp_rdata_q;
89	  reg rsp_error_q;
90	  reg rsp_page_fault_q;
91	  reg aw_done_q;
92	  reg w_done_q;
93	  reg drop_rsp_q;
94	  // B1 访存解耦：cacheable-PMEM store 在数据落 PMEM(AW&W fire)后即报完成、提前推进，
95	  // 其滞后的 AXI B 由 bpend_q 跟踪器在后台吸收，使紧随的 load 可与 B drain 重叠。
96	  // 仅对 PMEM(bresp 恒 OK)解耦；MMIO/可错 store 仍等 B 以保精确异常(MEM-I3)。详见
97	  // design/specs/ooo-mem-axi-bridge-fsm.md 与 design/arch/mem-store-decouple.md。
98	  reg bpend_q;
99	  // 【LSQ·SQ 切换】当前事务属性(advance 拍锁存, 每次 accept 覆盖)。pretrans 的效果
100	  // (跳过翻译/PMP)全部在 advance 拍组合完成, 无需再寄存进 FSM。
101	  reg probe_q;
102	  reg nokill_q;
103	  // 【P5 刀 M·桥侧 req 寄存站】req fire(=accept)拍只锁存 CPU 侧请求 8 字段, 零计算;
104	  // 翻译(DTLB CAM)/PMP/dcache 发射/全部分流决策整体推迟到 stage_advance 拍
105	  // (accept_request 改从寄存站取数)。必须留在 fire 拍的只有字段锁存本身——core 侧
106	  // req mux 是组合的、次拍即消失(SQ drain fire 次拍 drain_inflight_q 置位撤 valid,
107	  // probe 同理)。CSR 上下文(priv/mstatus/satp/svpbmt/pmp)不进寄存站: 寄存站占用 ⇒
108	  // MIQ 非空 ⇒ mem_idle=0 ⇒ head0-CSR/sfence 被 serialize-at-retire 挡住不能退休,
109	  // advance 拍上下文与 fire 拍必同(NpcSimTop 跨模块立即断言固化, 勿改为多锁上下文)。
110	  reg stg_valid_q;
111	  reg [`XLEN-1:0] stg_addr_q;
112	  reg [`XLEN-1:0] stg_wdata_q;
113	  reg [`STRB_W-1:0] stg_wstrb_q;
114	  reg stg_write_q;
115	  reg stg_probe_q;
116	  reg stg_pretrans_q;
117	  reg stg_nokill_q;
118	  // 【line-dcache】本读事务是否跨 8B line(跨线走窗口读不 fill; 不跨线发对齐
119	  // AR, 回填 line 并把窗口视图给 CPU)
120	  reg read_cross_q;
