122	  function [1:0] mstatus_mpp_priv;
123	    input [`XLEN-1:0] status;
124	    begin
125	      case (status & `MSTATUS_MPP_MASK)
126	        `MSTATUS_MPP_S: mstatus_mpp_priv = `PRIV_S;
127	        `MSTATUS_MPP_M: mstatus_mpp_priv = `PRIV_M;
128	        default:        mstatus_mpp_priv = `PRIV_U;
129	      endcase
130	    end
131	  endfunction
132	
133	  function [1:0] effective_data_priv;
134	    input [1:0] priv_mode;
135	    input [`XLEN-1:0] status;
136	    begin
137	      effective_data_priv =
138	          ((priv_mode == `PRIV_M) &&
139	           ((status & `MSTATUS_MPRV) != {`XLEN{1'b0}})) ?
140	          mstatus_mpp_priv(status) : priv_mode;
141	    end
142	  endfunction
143	
144	  function sv39_enabled;
145	    input [1:0] priv_mode;
146	    input [`XLEN-1:0] satp;
147	    begin
148	      sv39_enabled = (priv_mode != `PRIV_M) && (satp[63:60] == 4'h8);
149	    end
150	  endfunction
151	
152	  function canonical_sv39;
153	    input [`XLEN-1:0] vaddr;
154	    begin
155	      canonical_sv39 = (vaddr[63:39] == {25{vaddr[38]}});
156	    end
157	  endfunction
158	
159	  function [8:0] vpn_by_level;
160	    input [`XLEN-1:0] vaddr;
161	    input [1:0] level;
162	    begin
163	      case (level)
164	        2'd2: vpn_by_level = vaddr[38:30];
165	        2'd1: vpn_by_level = vaddr[29:21];
166	        default: vpn_by_level = vaddr[20:12];
167	      endcase
168	    end
169	  endfunction
170	
171	  function [`XLEN-1:0] pte_addr;
172	    input [43:0] ppn;
173	    input [`XLEN-1:0] vaddr;
174	    input [1:0] level;
175	    begin
176	      pte_addr = {8'b0, ppn, 12'b0} +
177	                 {{(`XLEN-12){1'b0}}, vpn_by_level(vaddr, level), 3'b000};
178	    end
179	  endfunction
180	
181	  function pte_invalid;
182	    input [`XLEN-1:0] pte;
183	    begin
184	      pte_invalid = !pte[0] || (!pte[1] && pte[2]);
185	    end
186	  endfunction
187	
188	  function pte_leaf;
189	    input [`XLEN-1:0] pte;
190	    begin
191	      pte_leaf = pte[1] || pte[3];
192	    end
193	  endfunction
194	
195	  function pte_reserved_fault;
196	    input [`XLEN-1:0] pte;
197	    input svpbmt_en;
198	    input [1:0] level;
199	    begin
200	      pte_reserved_fault =
201	          (pte_leaf(pte) ?
202	           (((pte & ((svpbmt_en ? `SV39_PTE_RESERVED_MASK_SVPBMT :
203	                                  `SV39_PTE_RESERVED_MASK) &
204	                                 ~`SV39_PTE_N)) != {`XLEN{1'b0}}) ||
205	            (((pte & `SV39_PTE_N) != {`XLEN{1'b0}}) &&
206	             ((level != 2'd0) || (pte[13:10] != 4'b1000)))) :
207	           (((pte & (svpbmt_en ? `SV39_PTE_RESERVED_MASK_SVPBMT :
208	                                  `SV39_PTE_RESERVED_MASK)) !=
209	             {`XLEN{1'b0}}) ||
210	            ((pte & `SV39_PTE_NONLEAF_RESERVED_MASK) != {`XLEN{1'b0}}) ||
211	            (svpbmt_en &&
212	             (pte[`SV39_PTE_PBMT_HI:`SV39_PTE_PBMT_LO] != 2'b00)))) ||
213	          (pte_leaf(pte) && svpbmt_en &&
214	           (pte[`SV39_PTE_PBMT_HI:`SV39_PTE_PBMT_LO] == 2'b11));
215	    end
216	  endfunction
217	
218	  function superpage_misaligned;
219	    input [`XLEN-1:0] pte;
220	    input [1:0] level;
221	    begin
222	      case (level)
223	        2'd2: superpage_misaligned = (|pte[27:10]);
224	        2'd1: superpage_misaligned = (|pte[18:10]);
225	        default: superpage_misaligned = 1'b0;
226	      endcase
227	    end
228	  endfunction
229	
230	  function data_read_ok;
231	    input [`XLEN-1:0] pte;
232	    input [`XLEN-1:0] status;
233	    begin
234	      data_read_ok =
235	          pte[1] ||
236	          (((status & `MSTATUS_MXR) != {`XLEN{1'b0}}) && pte[3]);
237	    end
238	  endfunction
239	
240	  function data_user_ok;
241	    input [`XLEN-1:0] pte;
242	    input [1:0] priv_mode;
243	    input [`XLEN-1:0] status;
244	    begin
245	      data_user_ok =
246	          (priv_mode == `PRIV_U) ? pte[4] :
247	          (pte[4] ? ((status & `MSTATUS_SUM) != {`XLEN{1'b0}}) : 1'b1);
248	    end
249	  endfunction
250	
251	  // HW A/D(Svadu, 对齐 NEMU): 权限 fault 只含真权限(R/W/X、U/S、MXR/SUM)。
252	  // A/D 缺失不再 fault, 改由 walker S_AD_UPDATE 写回 PTE 置位(见 data_ad_update_needed)。
253	  function data_permission_fault;
254	    input [`XLEN-1:0] pte;
255	    input write_access;
256	    input [1:0] priv_mode;
257	    input [`XLEN-1:0] status;
258	    begin
259	      data_permission_fault =
260	          (write_access ? !pte[2] : !data_read_ok(pte, status)) ||
261	          !data_user_ok(pte, priv_mode, status);
262	    end
263	  endfunction
264	
265	  // A/D 需 HW 更新: 真权限已过但 A=0(任意访问)或 D=0(store)。
266	  function data_ad_update_needed;
267	    input [`XLEN-1:0] pte;
268	    input write_access;
269	    begin
270	      data_ad_update_needed = !pte[6] || (write_access && !pte[7]);
271	    end
272	  endfunction
273	
274	  function [`XLEN-1:0] leaf_paddr;
275	    input [`XLEN-1:0] pte;
276	    input [`XLEN-1:0] vaddr;
277	    input [1:0] level;
278	    begin
279	      // Svnapot 64KiB leaf: PTE.PPN[3:0] 是 NAPOT 编码(1000)，真实 PA
280	      // 低 4 个 PPN bit 必须来自 VA[15:12]，否则 store 会落到错误 64KiB 子页。
281	      leaf_paddr = {8'b0,
282	                    (level == 2'd2) ?
283	                    {pte[53:28], vaddr[29:21], vaddr[20:12]} :
284	                    (level == 2'd1) ?
285	                    {pte[53:28], pte[27:19], vaddr[20:12]} :
286	                    (((pte & `SV39_PTE_N) != {`XLEN{1'b0}}) ?
287	                     {pte[53:14], vaddr[15:12]} :
288	                     pte[53:10]),
289	                    vaddr[11:0]};
290	    end
291	  endfunction
292	
293	  function [3:0] access_size_from_wstrb;
294	    input [`STRB_W-1:0] wstrb;
295	    integer byte_idx;
296	    begin
297	      access_size_from_wstrb = 4'd0;
298	      for (byte_idx = 0; byte_idx < `STRB_W; byte_idx = byte_idx + 1) begin
299	        if (wstrb[byte_idx])
300	          access_size_from_wstrb = access_size_from_wstrb + 4'd1;
301	      end
302	      if (access_size_from_wstrb == 4'd0)
303	        access_size_from_wstrb = 4'd1;
304	    end
305	  endfunction
306	
307	  wire [1:0] req_priv_w = effective_data_priv(priv_mode_i, mstatus_i);
308	  wire ctx_translate_w = sv39_enabled(req_priv_w, satp_i);
309	  // pretrans 请求地址已是 PA:跳过翻译(req_cache_addr_w 直取 req_addr)与 PMP(probe 拍已查)。
