626	      wstrb_q <= req_wstrb_w;
627	      probe_q <= stg_probe_q && req_write_w;
628	      nokill_q <= stg_nokill_q;
629	      rsp_rdata_q <= {`XLEN{1'b0}};
630	      rsp_error_q <= 1'b0;
631	      rsp_page_fault_q <= 1'b0;
632	      aw_done_q <= 1'b0;
633	      w_done_q <= 1'b0;
634	      if (req_data_pmp_fault_w) begin
635	        rsp_error_q <= 1'b1;
636	        rsp_page_fault_q <= 1'b0;
637	        state_q <= S_RESP;
638	      end else if (req_translate_w && req_dtlb_perm_fault_w) begin
639	        rsp_error_q <= 1'b1;
640	        rsp_page_fault_q <= 1'b1;
641	        state_q <= S_RESP;
642	      end else if (req_translate_w && !req_dtlb_hit_w) begin
643	        if (canonical_sv39(req_addr_w)) begin
644	          walk_level_q <= 2'd2;
645	          walk_ppn_q <= satp_i[43:0];
646	          state_q <= S_WALK_AR;
647	        end else begin
648	          rsp_error_q <= 1'b1;
649	          rsp_page_fault_q <= 1'b1;
650	          state_q <= S_RESP;
651	        end
652	      end else if (req_write_w) begin
653	        if (stg_probe_q) begin
654	          // 【LSQ·SQ 切换】write 探测:翻译+PMP 已过, 不写内存, PA 经 rsp_rdata 回传。
655	          rsp_rdata_q <= req_cache_addr_w;
656	          state_q <= S_RESP;
657	        end else begin
658	          state_q <= S_WRITE_REQ;
659	        end
660	      end else begin
661	        // 【SRAM 同步读】读路径统一经 S_LOOKUP: fire 拍已发 dcache 读
662	        // (req_read_lookup_fire_w, 与本分支条件严格一致), 次拍判决 hit/miss。
663	        state_q <= S_LOOKUP;
