672	      paging_q <= 1'b0;
673	      access_priv_q <= `PRIV_M;
674	      access_svpbmt_en_q <= 1'b0;
675	      walk_level_q <= 2'd0;
676	      walk_ppn_q <= 44'd0;
677	      addr_q <= {`XLEN{1'b0}};
678	      paddr_q <= {`XLEN{1'b0}};
679	      ad_pte_q <= {`XLEN{1'b0}};
680	      read_cross_q <= 1'b0;
681	      wdata_q <= {`XLEN{1'b0}};
682	      wstrb_q <= {`STRB_W{1'b0}};
683	      rsp_rdata_q <= {`XLEN{1'b0}};
684	      rsp_error_q <= 1'b0;
685	      rsp_page_fault_q <= 1'b0;
686	      aw_done_q <= 1'b0;
687	      w_done_q <= 1'b0;
688	      drop_rsp_q <= 1'b0;
