714	        // S_LOOKUP: dcache 读无外部副作用, flush 当拍直接释放。
715	        S_WALK_AR, S_READ_ADDR, S_LOOKUP: begin
716	          state_q <= S_IDLE;
717	          aw_done_q <= 1'b0;
718	          w_done_q <= 1'b0;
719	          drop_rsp_q <= 1'b0;
720	        end
