740	            aw_done_q <= aw_done_q || aw_fire_w;
741	            w_done_q <= w_done_q || w_fire_w;
742	            drop_rsp_q <= 1'b1;
743	            state_q <= ((aw_done_q || aw_fire_w) &&
744	                        (w_done_q || w_fire_w)) ? S_WRITE_RESP : S_WRITE_REQ;
745	          end else begin
746	            state_q <= S_IDLE;
747	            aw_done_q <= 1'b0;
748	            w_done_q <= 1'b0;
749	            drop_rsp_q <= 1'b0;
750	          end
751	        end
752	
753	        S_WRITE_RESP: begin
754	          if (lsu_axi_bvalid_i) begin
755	            state_q <= S_IDLE;
756	            aw_done_q <= 1'b0;
757	            w_done_q <= 1'b0;
758	            drop_rsp_q <= 1'b0;
759	          end else begin
760	            drop_rsp_q <= 1'b1;
761	          end
762	        end
