764	        S_AD_UPDATE: begin
765	          // A/D 写必达: 完成 AW/W + 吸收 B 后 drop(不续访问; re-exec 幂等重走)。
766	          if (aw_fire_w) aw_done_q <= 1'b1;
767	          if (w_fire_w) w_done_q <= 1'b1;
768	          if ((aw_done_q || aw_fire_w) && (w_done_q || w_fire_w) &&
769	              lsu_axi_bvalid_i) begin
770	            aw_done_q <= 1'b0;
771	            w_done_q <= 1'b0;
772	            drop_rsp_q <= 1'b0;
773	            state_q <= S_IDLE;
774	          end else begin
775	            drop_rsp_q <= 1'b1;
776	          end
777	        end
778	
779	        S_RESP: begin
780	          state_q <= S_IDLE;
781	          aw_done_q <= 1'b0;
782	          w_done_q <= 1'b0;
783	          drop_rsp_q <= 1'b0;
784	        end
785	
786	        default: begin
787	          state_q <= S_IDLE;
788	          aw_done_q <= 1'b0;
789	          w_done_q <= 1'b0;
790	          drop_rsp_q <= 1'b0;
791	        end
792	      endcase
793	      end else begin
794	      case (state_q)
795	        S_IDLE: begin
796	          // 【刀 M】accept 调用已上提为 stage_advance 最高优先分支, 本臂只清 done 位。
