830	                  data_permission_fault(lsu_axi_rdata_i, write_q,
831	                                        access_priv_q, mstatus_i)) begin
832	                rsp_error_q <= 1'b1;
833	                rsp_page_fault_q <= 1'b1;
834	                state_q <= S_RESP;
835	              end else if (walk_leaf_pmp_fault_w) begin
836	                rsp_error_q <= 1'b1;
837	                rsp_page_fault_q <= 1'b0;
838	                state_q <= S_RESP;
839	              end else if (walk_ad_needed_w) begin
840	                // HW A/D: 真权限过但 A/D 不足 → 写回置位 PTE(S_AD_UPDATE), B 后再续访问。
841	                ad_pte_q <= lsu_axi_rdata_i | PTE_A_BIT |
