923	            aw_done_q <= 1'b1;
924	          end
925	          if (w_fire_w) begin
926	            w_done_q <= 1'b1;
927	          end
928	          if ((aw_done_q || aw_fire_w) && (w_done_q || w_fire_w)) begin
