942	
943	        S_WRITE_RESP: begin
944	          if (lsu_axi_bvalid_i) begin
945	            rsp_rdata_q <= {`XLEN{1'b0}};
946	            rsp_error_q <= (lsu_axi_bresp_i != 2'b00);
