1016	      stg_addr_q <= mem0_req_addr_i;
1017	      stg_wdata_q <= mem0_req_wdata_i;
1018	      stg_wstrb_q <= mem0_req_wstrb_i;
1019	      stg_write_q <= mem0_req_write_i;
1020	      stg_probe_q <= mem0_req_probe_i;
1021	      stg_pretrans_q <= mem0_req_pretrans_i;
1022	      stg_nokill_q <= mem0_req_nokill_i;
1023	    end else if (stage_advance_w) begin
1024	      stg_valid_q <= 1'b0;
1025	    end else if (flush_i && !stg_nokill_q) begin
1026	      stg_valid_q <= 1'b0;
1027	    end
1028	  end
1029	
1030	`ifdef OOO_ASSERT
1031	  // 【store RMW 读口互斥】RMW 判决拍(rmw_busy)宏口被占, 桥侧不得出现任何
1032	  // 会用口的动作: 三源 lookup 发射意图/fill/S_LOOKUP 判决。由 FSM 状态互斥
1033	  // (RMW 判决拍状态∈{S_RESP,S_IDLE})+stage_advance 压制(刀 M 后 req 源随
1034	  // advance 迁移, !rmw_busy 项迁入 stage_advance_w)保证, 违反即门控链被破坏。
1035	  always @(posedge clk) begin
1036	    if (!rst && dcache_rmw_busy_w &&
1037	        (req_read_lookup_fire_w || walk_read_lookup_fire_w ||
1038	         ad_read_lookup_fire_w || dcache_read_fill_valid_w ||
1039	         (state_q == S_LOOKUP))) begin
1040	      $error("[MEM-RMW-PORT] RMW 判决拍出现 lookup/fill/S_LOOKUP: state=%0d req=%b walk=%b ad=%b fill=%b @%0t",
1041	             state_q, req_read_lookup_fire_w, walk_read_lookup_fire_w,
1042	             ad_read_lookup_fire_w, dcache_read_fill_valid_w, $time);
1043	      $fatal;
1044	    end
1045	  end
1046	
1047	  // 【刀 M·寄存站契约断言族】全部立即断言形态(SVA 命中 0 教训)。
1048	  reg assert_stg_valid_r;
1049	  reg assert_fire_r;
1050	  reg assert_nokill_hold_r;
1051	  reg [`XLEN-1:0] assert_stg_addr_r;
1052	  reg [`XLEN-1:0] assert_stg_wdata_r;
1053	  reg [`STRB_W-1:0] assert_stg_wstrb_r;
1054	  reg [3:0] assert_stg_attr_r;
1055	  always @(posedge clk) begin
1056	    if (rst) begin
1057	      assert_stg_valid_r <= 1'b0;
1058	      assert_fire_r <= 1'b0;
1059	      assert_nokill_hold_r <= 1'b0;
1060	    end else begin
1061	      // BRG-NOFIRE-FLUSH: flush 拍不得 fire(ready 含 !flush_i ⟺ 寄存站↔MIQ 双射,
1062	      // MIQ flush 分支是 else-if、flush 拍 push 被忽略)。
1063	      if (mem0_req_fire_w && flush_i) begin
1064	        $error("[BRG-NOFIRE-FLUSH] flush 拍出现 mem0_req fire @%0t", $time);
1065	        $fatal;
1066	      end
1067	      // BRG-ADV-NODROP: advance 只可能发生在 drop_rsp_q=0 的拍
1068	      // (S_IDLE/S_RESP 态 drop 恒 0 的 FSM 不变量, 上提 accept 分支依赖它)。
1069	      if (stage_advance_w && drop_rsp_q) begin
1070	        $error("[BRG-ADV-NODROP] drop_rsp_q=1 拍出现 stage_advance @%0t", $time);
1071	        $fatal;
1072	      end
1073	      // BRG-STG-LOOKUP: req 源 dcache lookup 只允许出现在 stage_advance 拍
1074	      // (fire 拍恒 0——旧"fire 拍发 lookup"路径已被寄存站切断)。
1075	      if (req_read_lookup_fire_w && !stage_advance_w) begin
1076	        $error("[BRG-STG-LOOKUP] 非 advance 拍出现 req 源 dcache lookup @%0t",
1077	               $time);
1078	        $fatal;
1079	      end
1080	      // BRG-STG-HOLD: 上拍占用且未重装(fire), 本拍仍占用 ⇒ 字段冻结(PSR-HOLD 型)。
1081	      if (assert_stg_valid_r && !assert_fire_r && stg_valid_q &&
1082	          ((stg_addr_q != assert_stg_addr_r) ||
1083	           (stg_wdata_q != assert_stg_wdata_r) ||
1084	           (stg_wstrb_q != assert_stg_wstrb_r) ||
1085	           ({stg_write_q, stg_probe_q, stg_pretrans_q, stg_nokill_q} !=
1086	            assert_stg_attr_r))) begin
1087	        $error("[BRG-STG-HOLD] stall 拍寄存站字段被改写 @%0t", $time);
1088	        $fatal;
1089	      end
1090	      // BRG-STG-NOKILL: flush 拍未 advance 的 nokill 项次拍必须存活(写必达)。
1091	      if (assert_nokill_hold_r && !stg_valid_q) begin
1092	        $error("[BRG-STG-NOKILL] flush 拍 nokill 寄存站项被丢弃 @%0t", $time);
1093	        $fatal;
1094	      end
1095	      assert_stg_valid_r <= stg_valid_q;
1096	      assert_fire_r <= mem0_req_fire_w;
1097	      assert_nokill_hold_r <= flush_i && stg_valid_q && stg_nokill_q &&
1098	                              !stage_advance_w;
1099	      assert_stg_addr_r <= stg_addr_q;
1100	      assert_stg_wdata_r <= stg_wdata_q;
1101	      assert_stg_wstrb_r <= stg_wstrb_q;
1102	      assert_stg_attr_r <= {stg_write_q, stg_probe_q, stg_pretrans_q,
1103	                            stg_nokill_q};
1104	    end
1105	  end
1106	`endif
1107	
1108	endmodule
1109

