content.content:
1	// AXI-Lite 到 UART native 寄存器接口的适配器。
2	// UART 本体不感知 AXI；本模块只负责把 single-beat AXI-Lite 事务翻译为
3	// UART 的单拍寄存器读写访问。
4	module AxiLiteToUart #(
5	  parameter ADDR_W = 32,
6	  parameter DATA_W = 32,
7	  parameter STRB_W = DATA_W / 8
8	) (
9	  input clk,
10	  input rst,
11	
12	  input s_axi_arvalid_i,
13	  output s_axi_arready_o,
14	  input [ADDR_W-1:0] s_axi_araddr_i,
15	  input [STRB_W-1:0] s_axi_arstrb_i,
16	  output reg s_axi_rvalid_o,
17	  input s_axi_rready_i,
18	  output reg [DATA_W-1:0] s_axi_rdata_o,
19	  output [1:0] s_axi_rresp_o,
20	
21	  input s_axi_awvalid_i,
22	  output s_axi_awready_o,
23	  input [ADDR_W-1:0] s_axi_awaddr_i,
24	  input s_axi_wvalid_i,
25	  output s_axi_wready_o,
26	  input [DATA_W-1:0] s_axi_wdata_i,
27	  input [STRB_W-1:0] s_axi_wstrb_i,
28	  output reg s_axi_bvalid_o,
29	  input s_axi_bready_i,
30	  output [1:0] s_axi_bresp_o,
31	
32	  output uart_tx_valid_o,
33	  output [7:0] uart_tx_data_o,
34	  output uart_access_valid_o,
35	  output uart_access_write_o,
36	  output [11:0] uart_access_addr_o,
37	  output [DATA_W-1:0] uart_access_wdata_o,
38	  output [STRB_W-1:0] uart_access_wstrb_o,
39	  output [DATA_W-1:0] uart_access_rdata_o,
40	  input uart_rx_valid_i,
41	  input [7:0] uart_rx_data_i,
42	  output uart_rx_ready_o,
43	  output uart_irq_o
44	);
45	
46	  reg [11:0] awaddr_low_q;
47	  reg aw_seen_q;
48	  reg [DATA_W-1:0] wdata_q;
49	  reg [STRB_W-1:0] wstrb_q;
50	  reg w_seen_q;
51	
52	  wire ar_fire_w = s_axi_arvalid_i && s_axi_arready_o;
53	  wire aw_fire_w = s_axi_awvalid_i && s_axi_awready_o;
54	  wire w_fire_w = s_axi_wvalid_i && s_axi_wready_o;
55	  wire write_done_w = !s_axi_bvalid_o &&
56	                      (aw_seen_q || aw_fire_w) &&
57	                      (w_seen_q || w_fire_w);
58	  wire [11:0] write_addr_low_w = aw_fire_w ? s_axi_awaddr_i[11:0] : awaddr_low_q;
59	  wire [DATA_W-1:0] write_data_w = w_fire_w ? s_axi_wdata_i : wdata_q;
60	  wire [STRB_W-1:0] write_strb_w = w_fire_w ? s_axi_wstrb_i : wstrb_q;
61	  wire [DATA_W-1:0] uart_rdata_w;
62	  wire unused_addr_hi_w = |{
63	      s_axi_araddr_i[ADDR_W-1:12],
64	      s_axi_awaddr_i[ADDR_W-1:12]
65	  };
66	
67	  assign s_axi_arready_o = !s_axi_rvalid_o;
68	  assign s_axi_rresp_o = 2'b00;
69	  assign s_axi_awready_o = !aw_seen_q && !s_axi_bvalid_o;
70	  assign s_axi_wready_o = !w_seen_q && !s_axi_bvalid_o;
71	  assign s_axi_bresp_o = 2'b00;
72	  assign uart_access_addr_o = write_done_w ? write_addr_low_w
73	                                           : s_axi_araddr_i[11:0];
74	  assign uart_access_wdata_o = write_done_w ? write_data_w
75	                                            : {DATA_W{1'b0}};
76	  assign uart_access_wstrb_o = write_done_w ? write_strb_w
77	                                            : {STRB_W{1'b0}};
78	  assign uart_access_rdata_o = ar_fire_w ? uart_rdata_w
79	                                         : {DATA_W{1'b0}};
80	
81	  Uart #(
82	    .DATA_W(DATA_W),
83	    .STRB_W(STRB_W)
84	  ) u_uart (
85	    .clk(clk),
86	    .rst(rst),
87	    .reg_read_valid_i(ar_fire_w),
88	    .reg_read_addr_i(s_axi_araddr_i[11:0]),
89	    .reg_read_strb_i(s_axi_arstrb_i),
90	    .reg_read_data_o(uart_rdata_w),
91	    .reg_write_valid_i(write_done_w),
92	    .reg_write_addr_i(write_addr_low_w),
93	    .reg_write_data_i(write_data_w),
94	    .reg_write_strb_i(write_strb_w),
95	    .rx_valid_i(uart_rx_valid_i),
96	    .rx_data_i(uart_rx_data_i),
97	    .rx_ready_o(uart_rx_ready_o),
98	    .tx_valid_o(uart_tx_valid_o),
99	    .tx_data_o(uart_tx_data_o),
100	    .access_valid_o(uart_access_valid_o),
101	    .access_write_o(uart_access_write_o),
102	    .irq_o(uart_irq_o)
103	  );
104	
105	  always @(posedge clk) begin
106	    if (rst) begin
107	      s_axi_rvalid_o <= 1'b0;
108	      s_axi_rdata_o <= {DATA_W{1'b0}};
109	      s_axi_bvalid_o <= 1'b0;
110	      awaddr_low_q <= 12'h000;
111	      aw_seen_q <= 1'b0;
112	      wdata_q <= {DATA_W{1'b0}};
113	      wstrb_q <= {STRB_W{1'b0}};
114	      w_seen_q <= 1'b0;
115	    end else begin
