    assign reg_write_strb_pad_w[7:4] = reg_write_strb_i[7:4];
  end else begin : gen_uart_strb_high_zero
    assign reg_read_strb_pad_w[7:4] = 4'b0;
    assign reg_write_strb_pad_w[7:4] = 4'b0;
  end
endgenerate

