107	bool npc_load_img_at(const char *image_path, npc_paddr_t load_addr) {
108	  FILE *fp = fopen(image_path, "rb");
109	  if (!fp) { perror("[npc] fopen image"); return false; }
110	
111	  if (fseek(fp, 0, SEEK_END) != 0) { perror("[npc] fseek"); fclose(fp); return false; }
112	  long image_size = ftell(fp);
113	  if (image_size < 0) { perror("[npc] ftell"); fclose(fp); return false; }
114	  if (fseek(fp, 0, SEEK_SET) != 0) { perror("[npc] rewind"); fclose(fp); return false; }
115	
116	  if (!npc_pmem_range_valid(load_addr, (size_t)image_size)) {
117	    fprintf(stderr, "[npc] image out of pmem: %s addr=0x%016" NPC_PRIxPADDR
118	                    " size=%ld, pmem=[0x%016" NPC_PRIxPADDR ",0x%016" NPC_PRIxPADDR "]\n",
119	            image_path, load_addr, image_size,
120	            (npc_paddr_t)NPC_PMEM_BASE,
121	            (npc_paddr_t)(NPC_PMEM_BASE + (npc_paddr_t)g_pmem_size - 1));
122	    fclose(fp); return false;
123	  }
124	
125	  /* 只清零 image 覆盖范围之外的 BSS 区域，不再整块 memset 128MB；
126	   * calloc 初始化时已经保证了全零基线。 */
127	  size_t nread = fread(npc_guest_to_host(load_addr), 1, (size_t)image_size, fp);
128	  fclose(fp);
129	
130	  if (nread != (size_t)image_size) {
131	    fprintf(stderr, "[npc] short read: expect %ld, got %zu\n", image_size, nread);
132	    return false;
133	  }
134	
135	  uint64_t image_end = (uint64_t)(load_addr - NPC_RESET_PC) + (uint64_t)image_size;
136	  if (load_addr >= NPC_RESET_PC && image_end > g_img_size) {
137	    g_img_size = (size_t)image_end;
138	  }
139	
140	  /* 支持真实固件启动时把 OpenSBI/kernel/DTB 分别装到指定物理地址。 */
141	  if (load_addr == NPC_RESET_PC) {
142	    LogBoth("The image is %s, size = %ld", image_path, image_size);
143	  } else {
144	    LogBoth("Load image %s at 0x%016" NPC_PRIxPADDR ", size = %ld",
145	            image_path, load_addr, image_size);
146	  }
147	  return true;
148	}
