154	bool npc_paddr_read(npc_paddr_t addr, npc_word_t *data, enum NpcBusAccess kind) {
155	  if (!data) return false;
156	
157	  /* 简易 csrc 仿真设备在 DPI 窗口 [NPC_DEVICE_BASE, NPC_DEVICE_TOP)=
158	   * [0x12000000, 0x14000000),已移出 pmem([0x80000000,0xbfffffff]),不再有别名遮挡。
159	   * 窗口内先走 MMIO;取指不穿设备。serial 由真 RTL UART 承载,不经此路径。 */
160	  if (kind != NPC_BUS_IFETCH && addr >= NPC_DEVICE_BASE && addr < NPC_DEVICE_TOP) {
161	    uint32_t mmio_data = 0;
162	    if (npc_mmio_read((uint32_t)addr, &mmio_data, kind)) {
163	      *data = (npc_word_t)mmio_data;
164	      npc_difftest_skip_ref();
165	      return true;
166	    }
167	  }
168	
169	  if (npc_in_pmem(addr)) {
170	    *data = host_read_word(npc_guest_to_host(addr));
171	    if (kind == NPC_BUS_LOAD && memwatch_hits(addr, sizeof(npc_word_t))) {
172	      Log("memwatch load addr=0x%016" NPC_PRIxPADDR " data=0x%016" NPC_PRIxWORD, addr, *data);
173	    }
174	    if (kind == NPC_BUS_LOAD && npc_mtrace_enabled()) {
175	      Log("mtrace load addr=0x%016" NPC_PRIxPADDR " data=0x%016" NPC_PRIxWORD, addr, *data);
176	    }
177	    return true;
178	  }
179	
180	  /* 取指不穿过 MMIO */
181	  if (kind != NPC_BUS_IFETCH) {
182	    uint32_t mmio_data = 0;
183	    if (npc_mmio_read((uint32_t)addr, &mmio_data, kind)) {
184	      *data = (npc_word_t)mmio_data;
185	      npc_difftest_skip_ref();
186	      return true;
187	    }
188	  }
189	
190	  fprintf(stderr, "[npc] %s out of bound at 0x%016" NPC_PRIxPADDR "\n", access_kind_name(kind), addr);
191	  return false;
192	}
