195	  /* 简易设备 DPI 窗口 [NPC_DEVICE_BASE, NPC_DEVICE_TOP);已移出 pmem,无别名遮挡。 */
196	  if (addr >= NPC_DEVICE_BASE && addr < NPC_DEVICE_TOP &&
197	      npc_mmio_write((uint32_t)addr, (uint32_t)data, (uint32_t)mask, kind)) {
198	    npc_difftest_skip_ref();
